  def notable
    return nil if @notable_type.nil? || @notable_id.nil?
    type = Cybertrain::Cast.str(@notable_type)
    key = Cybertrain::Cast.int(@notable_id)
    return nil if type == ""
    return @notable_record if @notable_loaded && @notable_loaded_key == key && @notable_loaded_type == type

