      message = "notable_type #{type.inspect} is not Photo or Post (the models that declare as: :notable)"
      raise ArgumentError, message
    end
    @notable_record =
      case type
      when "Photo" then Photo.find_by(id: key)
      when "Post" then Post.find_by(id: key)
      end
    @notable_loaded = true
    @notable_loaded_key = key
    @notable_loaded_type = type
    @notable_record
  end

